import * as THREE from 'three/webgpu';
import { uv, color, mix } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Dimensions
  const panelW = 3.4;
  const panelH = 1.9;

  // Colors
  const gradientTop = '#1a1a22';
  const gradientBottom = '#111116';
  const accentColor = '#ff2a38';
  const paperColor = '#e8ecf2';

  // === PANEL BACKGROUND ===
  const panelGeom = new THREE.PlaneGeometry(panelW, panelH);
  const panelMat = new THREE.MeshStandardNodeMaterial({
    colorNode: mix(
      color(gradientBottom),
      color(gradientTop),
      uv().y
    ),
    roughness: 0.6,
    metalness: 0.2,
    clearcoat: 0.1,
    transparent: true,
  });
  const panelMesh = new THREE.Mesh(panelGeom, panelMat);
  panelMesh.position.z = 0;
  group.add(panelMesh);

  // Positioning helpers
  const markPosX = -panelW / 2 + 0.5;
  const markPosY = panelH / 2 - 0.5;
  const markSize = 0.62;

  // === QUOTATION MARK ===
  const markMesh = ctx.fontAtlas
    ? ctx.fontAtlas.render('"', {
        font: 'Lora',
        fontSize: markSize,
        fontWeight: 600,
        color: accentColor,
      })
    : new THREE.Group();

  markMesh.position.set(markPosX, markPosY, 0.03);
  markMesh.scale.set(1.04, 1.04, 1.04);
  group.add(markMesh);

  // === QUOTE TEXT ===
  const quoteY = markPosY - markSize / 2 - 0.25;
  const quoteText = config.textContent?.quote || 
    "The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.";

  const quoteMesh = ctx.fontAtlas
    ? ctx.fontAtlas.render(quoteText, {
        font: 'Lora',
        fontSize: 0.20,
        fontWeight: 400,
        color: paperColor,
        maxWidth: 2.4,
        lineHeight: 1.45,
      })
    : new THREE.Group();

  quoteMesh.position.set(0, quoteY, 0.03);
  group.add(quoteMesh);

  // === ACCENT RULE ===
  const attrY = quoteY - 0.5;
  const ruleGeom = new THREE.PlaneGeometry(0.2, 0.02);
  const ruleMat = new THREE.MeshStandardNodeMaterial({
    color: accentColor,
    emissive: accentColor,
    emissiveIntensity: 1.4,
  });
  const ruleMesh = new THREE.Mesh(ruleGeom, ruleMat);
  ruleMesh.position.set(markPosX, attrY + 0.08, 0.03);
  group.add(ruleMesh);

  // === ATTRIBUTION TEXT ===
  const attributionText = config.textContent?.attribution || "M. OKAFOR";
  const attributionMesh = ctx.fontAtlas
    ? ctx.fontAtlas.render(attributionText, {
        font: 'JetBrains Mono',
        fontSize: 0.13,
        fontWeight: 700,
        color: paperColor,
        letterSpacing: 0.08,
        lineHeight: 1.2,
      })
    : new THREE.Group();

  attributionMesh.position.set(0, attrY, 0.03);
  group.add(attributionMesh);

  // === CAPTION TEXT ===
  const captionText = config.textContent?.caption || "COLLECTOR SINCE 2019";
  const captionY = attrY - 0.2;
  const captionMesh = ctx.fontAtlas
    ? ctx.fontAtlas.render(captionText, {
        font: 'JetBrains Mono',
        fontSize: 0.09,
        fontWeight: 400,
        color: paperColor,
        letterSpacing: 0.12,
        lineHeight: 1.4,
      })
    : new THREE.Group();

  captionMesh.position.set(0, captionY, 0.03);
  group.add(captionMesh);

  // === ANIMATIONS ===
  const timeline = gsap.timeline({ paused: false });

  // Panel fade-up: opacity 0 → 1, y +0.2 → 0 over 500ms
  panelMesh.position.y = 0.2;
  panelMat.opacity = 0;

  timeline.to(
    panelMat,
    {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );

  timeline.to(
    panelMesh.position,
    {
      y: 0,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );

  // Quote mark weighted-settle: scale 1.04 → 1.0 over 900ms, starts at 500ms
  timeline.to(
    markMesh.scale,
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
    },
    0.5
  );

  // === CLEANUP ===
  group.userData.cleanup = () => {
    timeline.kill();
    panelGeom.dispose();
    panelMat.dispose();
    ruleGeom.dispose();
    ruleMat.dispose();
  };

  group.userData.handlers = {};

  return group;
}
